import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { z } from 'zod';
import type { Database } from './client.ts';

/** Reviewed SQL migrations generated by drizzle-kit (forward-only, ADR 0003). */
export const migrationsFolder = fileURLToPath(new URL('./migrations', import.meta.url));

export type MigrationOutcome = 'applied' | 'no-migrations';

const journalSchema = z.object({ entries: z.array(z.unknown()) });

const countJournalEntries = async (folder: string): Promise<number> => {
  const path = join(folder, 'meta', '_journal.json');
  let text: string;
  try {
    text = await readFile(path, 'utf8');
  } catch (error: unknown) {
    if (error instanceof Error && 'code' in error && error.code === 'ENOENT') {
      return 0;
    }
    throw new Error(`Cannot read migration journal ${path}`, { cause: error });
  }
  return journalSchema.parse(JSON.parse(text)).entries.length;
};

/**
 * Applies pending migrations in order (tracked in Drizzle's migrations table). Until the first
 * migration is generated there is no (or an empty) journal; that is reported, not an error.
 */
export const runMigrations = async (
  db: Database,
  folder: string = migrationsFolder,
): Promise<MigrationOutcome> => {
  if ((await countJournalEntries(folder)) === 0) {
    return 'no-migrations';
  }
  await migrate(db, { migrationsFolder: folder });
  return 'applied';
};
